create extension if not exists pgcrypto;
create table if not exists public.reviews(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 1 and 50),rating integer not null check(rating between 1 and 5),comment text not null check(char_length(comment) between 1 and 500),created_at timestamptz not null default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),title text not null check(char_length(title) between 1 and 120),message text not null check(char_length(message) between 1 and 1000),active boolean not null default true,start_date date,end_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date is null or start_date is null or end_date>=start_date));
alter table public.reviews enable row level security; alter table public.notifications enable row level security;
drop policy if exists "Public can read reviews" on public.reviews; create policy "Public can read reviews" on public.reviews for select using(true);
drop policy if exists "Public can add reviews" on public.reviews; create policy "Public can add reviews" on public.reviews for insert with check(true);
drop policy if exists "Admins can delete reviews" on public.reviews; create policy "Admins can delete reviews" on public.reviews for delete using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists "Public can read active notifications" on public.notifications; create policy "Public can read active notifications" on public.notifications for select using(((active=true and (start_date is null or start_date<=current_date) and (end_date is null or end_date>=current_date)) or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')));
drop policy if exists "Admins can insert notifications" on public.notifications; create policy "Admins can insert notifications" on public.notifications for insert with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists "Admins can update notifications" on public.notifications; create policy "Admins can update notifications" on public.notifications for update using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists "Admins can delete notifications" on public.notifications; create policy "Admins can delete notifications" on public.notifications for delete using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
do $$ begin alter publication supabase_realtime add table public.notifications; exception when duplicate_object then null; end $$;
do $$ begin alter publication supabase_realtime add table public.reviews; exception when duplicate_object then null; end $$;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists notifications_updated_at on public.notifications; create trigger notifications_updated_at before update on public.notifications for each row execute function public.set_updated_at();
